const canvas=document.querySelector('#society'),ctx=canvas.getContext('2d'),slider=document.querySelector('#affinity'),pause=document.querySelector('#pause'),state=document.querySelector('#state');let width=500,height=390,agents=[],running=!matchMedia('(prefers-reduced-motion: reduce)').matches,last=0;const colors=['#e14335','#e7dfd2','#878483'];function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;canvas.width=width*devicePixelRatio;canvas.height=height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}function reset(){agents=Array.from({length:90},(_,i)=>({x:Math.random()*width,y:Math.random()*height,vx:(Math.random()-.5)*1.5,vy:(Math.random()-.5)*1.5,group:i%3}));draw()}function draw(){ctx.clearRect(0,0,width,height);for(const a of agents){for(const b of agents){const d=Math.hypot(a.x-b.x,a.y-b.y);if(a!==b&&a.group===b.group&&d<65){ctx.strokeStyle=colors[a.group];ctx.globalAlpha=(1-d/65)*.18;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}ctx.globalAlpha=1;ctx.fillStyle=colors[a.group];ctx.beginPath();ctx.arc(a.x,a.y,3.3,0,Math.PI*2);ctx.fill()}}function step(t){if(running&&t-last>25){last=t;const strength=Number(slider.value)/100;for(const a of agents){let dx=0,dy=0,n=0;for(const b of agents){if(a===b)continue;const x=b.x-a.x,y=b.y-a.y,d=Math.hypot(x,y);if(d<12&&d>0){a.vx-=x/d*.07;a.vy-=y/d*.07}if(a.group===b.group&&d<150){dx+=x;dy+=y;n++}}if(n){a.vx+=dx/n*.0009*strength;a.vy+=dy/n*.0009*strength}a.vx+=(Math.random()-.5)*.1*(1-strength+.1);a.vy+=(Math.random()-.5)*.1*(1-strength+.1);const speed=Math.hypot(a.vx,a.vy);if(speed>1.6){a.vx*=1.6/speed;a.vy*=1.6/speed}a.x+=a.vx;a.y+=a.vy;if(a.x<6||a.x>width-6){a.vx*=-1;a.x=Math.max(6,Math.min(width-6,a.x))}if(a.y<6||a.y>height-6){a.vy*=-1;a.y=Math.max(6,Math.min(height-6,a.y))}}draw()}requestAnimationFrame(step)}function sync(){pause.textContent=running?'Pause':'Play';pause.setAttribute('aria-pressed',String(!running));state.textContent=running?'SIMULATION RUNNING':'SIMULATION PAUSED'}slider.addEventListener('input',()=>document.querySelector('#value').textContent=slider.value+'%');pause.addEventListener('click',()=>{running=!running;sync()});document.querySelector('#reset').addEventListener('click',reset);new ResizeObserver(()=>{resize();for(const a of agents){a.x=Math.min(a.x,width-6);a.y=Math.min(a.y,height-6)}draw()}).observe(canvas);resize();reset();sync();requestAnimationFrame(step);
